if go_check=1 and 2>attack_waits
{
mp_potential_step(go_x, go_y, move_speed, 0)
}
//명령전송 받으면 이동, 모습변경

if x=go_x and y=go_y and go_check=1
{
go_check=0
attack_waits=1
}
//지정위치 가면 명령지움


if move_speed!=0
{


if go_check=1
{
obj_place = instance_place(x, y, obj_unit)
if obj_place != noone
{
if obj_place.go_check=0 and go_x=obj_place.go_x and go_y=obj_place.go_y
{go_x=x+choose(-5,+5); go_y=y+choose(-5,+5); go_check=1}}
}
//가는도중 어떤 나랑 같은 위치인 놈이 쉬고잇으면 퍼짐

obj_place=instance_place(x, y,obj_unit)
if obj_place!=noone
{
x+=lengthdir_x(1,point_direction(x, y, obj_place.x, obj_place.y)+180)
y+=lengthdir_y(1,point_direction(x, y, obj_place.x, obj_place.y)+180)
}
//어떤놈이랑박으면 퍼짐


}

room_block()

if unit_s=1
{

if attack_waits=1
{
attack_unit=sk_obj_seek(obj_unit, attack_range)
if attack_unit!=noone{attack_waits=2}
else
{
attack_unit=sk_obj_seek(obj_bil, attack_range)
if attack_unit!=noone{attack_waits=2}
}
}
//어택 대기일때 검색

if attack_waits=2 and alarm[0]=-1
{
if global.player_com[player]=1 and attack_range=99999{attack_range=attack_range2; attack_waits=4}
//컴터면 인공이삭제

if instance_number(attack_unit)=0{attack_waits=1; attack_unit=noone}
//어택일때 해당유닛이죽으면

if distance_to_object(attack_unit)>attack_range{attack_waits=1; attack_unit=noone}
//공격하던놈이 범위를나가면

if attack_unit!=noone
{
mp_potential_step(attack_unit.x, attack_unit.y, move_speed, 0)
if 100>unit_id{image_index=round(point_direction(x, y, attack_unit.x, attack_unit.y)/90)}
}
//아니면 공격

if distance_to_object(attack_unit)<3{attack_waits=3}
}

if attack_waits=4 and alarm[0]=-1
{
if instance_number(attack_unit)=0{attack_waits=1; attack_unit=noone}
//어택일때 해당유닛이죽으면

if attack_unit!=noone
{
mp_potential_step(attack_unit.x, attack_unit.y, move_speed, 0)
if 100>unit_id{image_index=round(point_direction(x, y, attack_unit.x, attack_unit.y)/90)}
}
//아니면 공격

if distance_to_object(attack_unit)<3{attack_waits=3}
}

if attack_waits=3
{
if alarm[0]=-1
{
alarm[0]=attack_speed
}
}

}

if unit_s=2
{

if attack_waits=1
{
attack_unit=sk_obj_seek(obj_unit, attack_range)
if attack_unit!=noone{attack_waits=2}
else
{
attack_unit=sk_obj_seek(obj_bil, attack_range)
if attack_unit!=noone{attack_waits=2}
}
}
//어택 대기일때 검색

if attack_waits=2 and alarm[0]=-1
{
if global.player_com[player]=1 and attack_range=99999{attack_range=attack_range2; attack_waits=4}
//컴터면 인공이삭제

if instance_number(attack_unit)=0{attack_waits=1; attack_unit=noone}
//어택일때 해당유닛이죽으면

if distance_to_object(attack_unit)>attack_range{attack_waits=1; attack_unit=noone}
//공격하던놈이 범위를나가면

if attack_unit!=noone
{
attack_waits=3
if 100>unit_id{image_index=round(point_direction(x, y, attack_unit.x, attack_unit.y)/90)}
}
//아니면 공격
}

if attack_waits=4 and alarm[0]=-1
{
if instance_number(attack_unit)=0{attack_waits=1; attack_unit=noone}
//어택일때 해당유닛이죽으면

if attack_unit!=noone
{
mp_potential_step(attack_unit.x, attack_unit.y, move_speed, 0)
if 100>unit_id{image_index=round(point_direction(x, y, attack_unit.x, attack_unit.y)/90)}

if distance_to_object(attack_unit)<attack_range{attack_waits=3}
}
//아니면 공격
}

if attack_waits=3
{
if alarm[0]=-1
{
alarm[0]=attack_speed
}
}

}

if moni_go_waits=1
{
moni_go_waits_id=sk_obj_seek2(obj_moni, 500)
if moni_go_waits_id!=noone{moni_go_waits=2}
}

if moni_go_waits=2
{
if instance_number(moni_go_waits_id)
{
mp_potential_step(moni_go_waits_id.x, moni_go_waits_id.y, move_speed, 0)
if 100>unit_id{image_index=round(point_direction(x, y, moni_go_waits_id.x, moni_go_waits_id.y)/90)}

if distance_to_object(moni_go_waits_id)<3
{
if moni_go_waits_id.waits=0{moni_go_waits=3; moni_go_waits_id.waits=1}
else{moni_go_waits=1}
}
}
else{moni_go_waits=1}
}

if moni_go_waits=3
{
if alarm[1]=-1
{
alarm[1]=attack_speed
}
}

if moni_go_waits=4
{
moni_go_waits_id2=sk_obj_seek3(obj_unit, 500)
if moni_go_waits_id2!=noone{moni_go_waits=5}
}

if moni_go_waits=5
{
if instance_number(moni_go_waits_id2)
{
mp_potential_step(moni_go_waits_id2.x, moni_go_waits_id2.y, move_speed, 0)
if 100>unit_id{image_index=round(point_direction(x, y, moni_go_waits_id2.x, moni_go_waits_id2.y)/90)}

if distance_to_object(moni_go_waits_id2)<3
{
global.player_moni[global.player_control]+=attack_power
moni_go_waits=1
}
}
else{moni_go_waits=4}
}

with(obj_unit){if player=global.player_control{other.ok_rr=1}}
if ok_rr=0{with(obj_bil){if player=global.player_control{other.ok_rr=1}}}

if (4>global.player_control and 4>player) or (global.player_control>=4 and player>=4) or ok_rr=0
{
sk_fog_obj(sys_fog, x, y, range, 0)
}
//투명

if 0>=hp
{
if (4>global.player_control and 4>player) or (global.player_control>=4 and player>=4) or ok_rr=0{sk_fog_obj(sys_fog, x, y, range, 2)}
if global.player_control=player or global.player_com[player]=1
{
instance_destroy()
}
//포그반투명
}

if 100>unit_id{image_speed=0}
else{image_speed=0.5}

if unit_cre_time=0
{
sk_message_save(sk_get_o_space(), -2, 2, unit_cre_id[0], player)
sk_message_send()

for(i=1; i!=unit_cre_number; i+=1)
{
unit_cre_id[i-1]=unit_cre_id[i]
}
unit_cre_number-=1

if unit_cre_number>0{unit_cre_time=global.moni_alarm[unit_cre_id[0]]}
}

if unit_cre_time!=-1
{
unit_cre_time-=1
}

if sk_obj_me_check()
{

for(i=0; i!=sk_get_ome_max(); i+=1)
{

if sk_me_obj_read(i, 0, 0)=0
{
x=sk_me_obj_read(i, 0, 1)
y=sk_me_obj_read(i, 0, 2)
hp=sk_me_obj_read(i, 0, 3)
go_check=sk_me_obj_read(i, 0, 4)
go_x=sk_me_obj_read(i, 0, 5)
go_y=sk_me_obj_read(i, 0, 6)
attack_waits=sk_me_obj_read(i, 0, 7)
attack_unit=sk_me_obj_read(i, 0, 8)
oni_go_waits=sk_me_obj_read(i, 0, 9)
moni_go_waits_id=sk_me_obj_read(i, 0, 10)
image_index=sk_me_obj_read(i, 0, 11)
}
//능력치

if sk_me_obj_read(i, 0, 0)=1
{
if (4>global.player_control and 4>player) or (global.player_control>=4 and player>=4){sk_fog_obj(sys_fog, x, y, range, 2)}
instance_destroy()
}
//뒈짐

if sk_me_obj_read(i, 0, 0)=2
{
ins=instance_create(x, bbox_bottom+sprite_get_bbox_bottom(global.unit_id_spr[sk_me_obj_read(i, 0, 1), 0]), obj_unit)
ins.unit_id=sk_me_obj_read(i, 0, 1)
ins.player=sk_me_obj_read(i, 0, 2)
with(ins){sk_unit_skil_to(unit_id)}
}
//생산

}

sk_ome_clear()
}
